/**
 * @file        build-bravojs-bundle.js
 * @description Flattens ../corset-module.js (Emscripten build, -sSINGLE_FILE=1
 *              so the .wasm is already base64-embedded -- no separate binary
 *              to hand-embed, unlike ffmpeg-dcp's build) + ../corset-wasm.js
 *              (the runCorset() MEMFS wrapper) into one file wrapped in
 *              bravojs's module format (module.declare), the format DCP's
 *              package publisher expects -- see
 *              docs/patching-wasm-libraries-for-dcp.html in the Edequity
 *              repo (the same pattern used for fftw3wasm-v3, cfitsio4wasm,
 *              sofia2wasm, ffmpeg-wasm-test). Local (unpublished)
 *              job.requires() tolerates plain CommonJS because it goes
 *              through a real webpack build at deploy time; publish does
 *              not, so this file is pre-wrapped instead.
 *
 * @usage       node build-bravojs-bundle.js
 *              (run after ../build-wasm.sh; writes ./corset-wasm.js)
 */
'use strict';

const fs = require('fs');
const path = require('path');

const SRC_DIR = path.join(__dirname, '..');

const moduleSrc = fs.readFileSync(path.join(SRC_DIR, 'corset-module.js'), 'utf8');
let wrapperSrc = fs.readFileSync(path.join(SRC_DIR, 'corset-wasm.js'), 'utf8');

// corset-wasm.js normally does `const CorsetModule = require('./corset-module.js');`
// In the bundle, CorsetModule is supplied as a closure parameter instead --
// drop that one line, leave everything else (including the docblock) intact.
const requireLine = "const CorsetModule = require('./corset-module.js');\n";
if (!wrapperSrc.includes(requireLine)) {
  throw new Error("expected to find require('./corset-module.js') line in corset-wasm.js");
}
wrapperSrc = wrapperSrc.replace(requireLine, '');

const bundle = `/**
 * @file        corset-wasm.js (published bundle)
 * @description Published-package form of corset-module.js + corset-wasm.js,
 *              flattened into one file and wrapped in bravojs's module format
 *              (module.declare), per the DCP package publishing convention --
 *              see docs/patching-wasm-libraries-for-dcp.html in the Edequity
 *              repo. Generated by build-bravojs-bundle.js; do not hand-edit --
 *              edit ../corset-wasm.js or rerun ../build-wasm.sh + this script
 *              instead.
 *
 * @usage       job.requires(['corset-test/corset-wasm.js']);
 *              // inside the work function:
 *              const { runCorset } = require('corset-wasm.js');  // bare filename, no ./
 *              const { clusters, counts, log } = await runCorset(eqClassFiles, ['-d', '0.3']);
 */
module.declare([], function (require, exports, module) {
  // ---- corset-module.js (Emscripten build of Corset, BAM support compiled
  // out -- see corset-nobam.patch), verbatim, evaluated as a CommonJS module
  // body. -sSINGLE_FILE=1 means the .wasm is already base64-embedded in
  // here, so unlike ffmpeg-dcp's bundle there's no second binary to splice
  // in by hand. ----
  var CorsetModule = (function () {
    var module = { exports: {} };
    var exports = module.exports;
${moduleSrc}
    return module.exports;
  })();

  // ---- corset-wasm.js, with require('./corset-module.js') replaced by the ----
  // ---- CorsetModule captured above ----
  var bundleExports = (function (CorsetModule) {
    var module = { exports: {} };
    var exports = module.exports;
${wrapperSrc}
    return module.exports;
  })(CorsetModule);

  for (var k in bundleExports) {
    if (Object.prototype.hasOwnProperty.call(bundleExports, k)) exports[k] = bundleExports[k];
  }
});
`;

const outPath = path.join(__dirname, 'corset-wasm.js');
fs.writeFileSync(outPath, bundle);
console.log(`wrote ${outPath} (${(bundle.length / 1024).toFixed(0)} KB)`);
